UPDATE SCH_SGIC.AUX_USUARIO_OUTRAS_ENTIDADES
   SET MATRICULA = LPAD(TRIM(MATRICULA),11,'0')
 WHERE CHARACTER_LENGTH (TRIM(MATRICULA)) < 11;

-- REMOVE CARACTERES NÃO NUMÉRICOS NA MATRICULA_CHEFIA
UPDATE SCH_SGIC.AUX_USUARIO_OUTRAS_ENTIDADES
 SET MATRICULA_CHEFIA =  REGEXP_REPLACE(MATRICULA_CHEFIA, '[^0-9]', '', 'gi');

-- VERIFICA INEXISTENCIA DE 11 CARACTERES PARA A MATRÍCULA CHEFIA
SELECT MIN(CHARACTER_LENGTH(MATRICULA_CHEFIA))
  FROM SCH_SGIC.AUX_USUARIO_OUTRAS_ENTIDADES;

UPDATE SCH_SGIC.AUX_USUARIO_OUTRAS_ENTIDADES
   SET MATRICULA_CHEFIA = LPAD(TRIM(MATRICULA_CHEFIA),11,'0')
 WHERE CHARACTER_LENGTH (TRIM(MATRICULA_CHEFIA)) < 11;
